Fixpoint expr_setv (e : expr) (L : list bool) : list bool :=
  match e with
  | ELit _ => L
  | EVar n => if bm_get4 L n then L else bm_set L n
  | EAlu _ x y | EAluw _ x y | EMd _ x y | EMdw _ x y => expr_setv x (expr_setv y L)
  | EExt _ _ _ x => expr_setv x L
  | EBlob _ _ _ _ => L
  end.
