Fixpoint expr_vars_ltF (b : nat) (e : expr) : bool :=
  match e with
  | ELit _ => true
  | EVar n => ltb4 n b
  | EAlu _ x y | EAluw _ x y | EMd _ x y | EMdw _ x y => if expr_vars_ltF b x then expr_vars_ltF b y else false
  | EExt _ _ _ x => expr_vars_ltF b x
  | EBlob _ _ _ _ => true
  end.
